logger.message:
#[output application/json --- {message: 'get-order-status failed: ' ++ error.description, tracePoint: 'EXCEPTION'} ++ ({
            orderId: vars.orderId default 'unknown',
            errorType: error.errorType.identifier default 'UNKNOWN',
            errorDescription: error.description
          })]

mcp:tool-listener.mcp:parameters-schema:
{
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "orderId":     { "type": "string", "description": "Pedido relacionado (ex.: TW-1001)", "pattern": "^TW-[0-9]{4}$" },
          "subject":     { "type": "string", "description": "Resumo curto do problema", "minLength": 5, "maxLength": 100 },
          "description": { "type": "string", "description": "Descrição detalhada do problema relatado pelo cliente", "minLength": 10, "maxLength": 2000 },
          "priority":    { "type": "string", "description": "Prioridade do case", "enum": ["Low", "Medium", "High"] }
        },
        "required": ["orderId", "subject", "description", "priority"]
      }

salesforce:create.salesforce:records:
#[output application/java
---
[{
  Subject: "[" ++ vars.toolInput.orderId ++ "] " ++ vars.toolInput.subject,
  Description: vars.toolInput.description,
  Priority: vars.toolInput.priority,
  Origin: "Web",
  Status: "New"
}]
]

logger.message:
#[output application/json --- {message: 'create-support-case failed: ' ++ error.description, tracePoint: 'EXCEPTION'} ++ ({
            orderId: vars.toolInput.orderId default 'unknown',
            errorType: error.errorType.identifier default 'UNKNOWN',
            errorDescription: error.description
          })]

mcp:tool-listener.mcp:parameters-schema:
{
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "paymentIntentId": { "type": "string", "description": "Id do PaymentIntent no Stripe (ex.: pi_3Abc...)", "pattern": "^pi_[A-Za-z0-9_]+$" },
          "reason":          { "type": "string", "description": "Motivo do reembolso", "enum": ["duplicate", "fraudulent", "requested_by_customer"] }
        },
        "required": ["paymentIntentId", "reason"]
      }

logger.message:
#[output application/json --- {message: 'refund-payment failed: ' ++ error.description, tracePoint: 'EXCEPTION'} ++ ({
            paymentIntentId: vars.toolInput.paymentIntentId default 'unknown',
            errorType: error.errorType.identifier default 'UNKNOWN',
            errorDescription: error.description
          })]

mcp:tool-listener.mcp:parameters-schema:
{
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "message": { "type": "string", "description": "Mensagem a enviar ao canal de suporte", "minLength": 5, "maxLength": 1000 }
        },
        "required": ["message"]
      }

http:request.http:body:
#[output application/json
---
{
  channel: p('config.slack.channel'),
  text: ":bell: *TechWave Suporte* — " ++ vars.toolInput.message
}]

logger.message:
#[output application/json --- {message: 'notify-team failed: ' ++ error.description, tracePoint: 'EXCEPTION'} ++ ({
            errorType: error.errorType.identifier default 'UNKNOWN',
            errorDescription: error.description
          })]
